insert into public.pulse_challenge_templates (id, code, title, description, category, difficulty, points, answer_type, options, scoring_rule, required_facts, active, priority, cooldown_days, tags)
select 'cht_' || lower(code), code, title, description, category, difficulty, points, "answerType", options, rule, array['home_score','away_score']::text[], true, priority, cooldown, array(select jsonb_array_elements_text(tags))
from jsonb_to_recordset($json$[{"code":"TOTAL_EQ_12","title":"¿El total será exactamente 12 carreras?","description":"Se corrige con el marcador final.","category":"dificultad","difficulty":"expert","points":10,"answerType":"boolean","options":[{"id":"si","label":"Sí"},{"id":"no","label":"No"}],"rule":{"op":"total_eq","n":12},"priority":0,"cooldown":2,"tags":["dificultad"]},{"code":"PARITY_EVEN","title":"¿El total de carreras será un número par?","description":"Se corrige con el marcador final.","category":"total","difficulty":"easy","points":2,"answerType":"boolean","options":[{"id":"si","label":"Sí"},{"id":"no","label":"No"}],"rule":{"op":"parity","even":true},"priority":0,"cooldown":2,"tags":["total"]},{"code":"PARITY_ODD","title":"¿El total de carreras será un número impar?","description":"Se corrige con el marcador final.","category":"total","difficulty":"easy","points":2,"answerType":"boolean","options":[{"id":"si","label":"Sí"},{"id":"no","label":"No"}],"rule":{"op":"parity","even":false},"priority":0,"cooldown":2,"tags":["total"]},{"code":"TOTAL_BUCKET_A","title":"¿En qué rango cae el total de carreras?","description":"Elige el rango. Se corrige con el marcador final.","category":"total","difficulty":"medium","points":4,"answerType":"multiple","options":[{"id":"lt6","label":"Menos de 6"},{"id":"6a8","label":"6 a 8"},{"id":"9a11","label":"9 a 11"},{"id":"12p","label":"12 o más"}],"rule":{"op":"buckets","fact":"total","buckets":[{"id":"lt6","label":"Menos de 6","min":0,"max":5},{"id":"6a8","label":"6 a 8","min":6,"max":8},{"id":"9a11","label":"9 a 11","min":9,"max":11},{"id":"12p","label":"12 o más","min":12,"max":null}]},"priority":1,"cooldown":2,"tags":["total","rango"]}]$json$::jsonb) as t(code text, title text, description text, category text, difficulty text, points int, "answerType" text, options jsonb, rule jsonb, priority int, cooldown int, tags jsonb)
on conflict (code) do nothing;